#!/usr/bin/env python3
# Builds the two ONE-CALL files for the Supabase SQL editor (no psql needed):
#   RUN_1_DRYRUN_SINGLE_CALL.sql  : repo script + wrapper; returns ONE row with the full report; always rolls back (nothing kept).
#   RUN_2_REAL_SINGLE_CALL.sql    : pre-checks (abort before anything is touched) + repo script + the real call; COMMITS only if every in-script check passes.
# Inputs: ../wipe_operational_data.sql (unchanged), params below (approved numbers; the script refuses if live counts differ).
# Usage: python3 build_single_call.py [--fk-digest D --trg-digest D]   (defaults = production values captured 26 Nov ~14:45 UK)
import json, sys, pathlib, hashlib
here = pathlib.Path(__file__).resolve().parent
script = (here.parent / "wipe_operational_data.sql").read_text()
EXPECT_SHA = "ae08ae14b87441cb1457bf424efb4e28e127938f5e913c0aa639f848a634b69a"
assert hashlib.sha256(script.encode()).hexdigest() == EXPECT_SHA, "wipe_operational_data.sql changed: re-review before building"
fk = "91d36c59a57faee3822ad0a59e7d401e"; trg = "9f4cb4c66625cdd6b4f1333ccc3415ea"; nfk, ntrg = 521, 485
a = sys.argv[1:]
if "--fk-digest" in a: fk = a[a.index("--fk-digest") + 1]
if "--trg-digest" in a: trg = a[a.index("--trg-digest") + 1]
if "--nfk" in a: nfk = int(a[a.index("--nfk") + 1])
if "--ntrg" in a: ntrg = int(a[a.index("--ntrg") + 1])
params = json.loads((here / "params_2026-11-26.DRAFT.json").read_text())
J, M = "264fe031-5381-4d70-a8fd-113c1713bc65", "2a213c03-c440-450d-9217-e2bbfcaff6b5"
params.pop("_note", None)
params["expected"] = {J: {"customers": 9, "suppliers": 9, "quotes": 28, "jobs": 27, "sales_orders": 21, "purchase_orders": 10, "delivery_notes": 10, "invoices": 20, "machines": 1, "stock": 6},
                      M: {"customers": 1, "quotes": 3, "jobs": 2, "sales_orders": 1, "invoices": 1}}
dry = dict(params, dry_run=True); real = dict(params, dry_run=False)
q = lambda p: json.dumps(p, separators=(",", ":"))
wrapper = """
-- ONE-CALL wrapper: runs the whole script and returns its report (or the refusal) as a row. The wipe rolls back inside the wrapper's block, so nothing is kept.
CREATE OR REPLACE FUNCTION pg_temp.dry_report(p jsonb) RETURNS jsonb LANGUAGE plpgsql AS $w$
DECLARE d text;
BEGIN
  PERFORM pg_temp.tolra_wipe(p);
  RETURN jsonb_build_object('UNEXPECTED', 'the dry run returned normally');
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS d = PG_EXCEPTION_DETAIL;
  RETURN jsonb_build_object('sqlstate', SQLSTATE, 'message', SQLERRM, 'expected_message', 'DRY_RUN_ROLLED_BACK', 'report', CASE WHEN SQLERRM = 'DRY_RUN_ROLLED_BACK' THEN d::jsonb ELSE to_jsonb(d) END);
END $w$;
"""
pre = """
-- PRE-CHECKS: any failure raises BEFORE the wipe starts (nothing touched, nothing committed).
DO $pre$ BEGIN
  IF NOT (current_user = 'postgres' AND session_user = 'postgres' AND coalesce(nullif(current_setting('role', true), 'none'), 'none') = 'none') THEN RAISE EXCEPTION 'PRECHECK: not running as postgres'; END IF;
  IF (SELECT count(*) FROM public.organizations) <> 3 THEN RAISE EXCEPTION 'PRECHECK: organizations <> 3'; END IF;
  IF (SELECT count(*) FROM security_audit.audit_log WHERE action = 'DATA_WIPE') <> 0 THEN RAISE EXCEPTION 'PRECHECK: a DATA_WIPE row already exists'; END IF;
  IF EXISTS (SELECT 1 FROM pg_trigger g JOIN pg_class c ON c.oid = g.tgrelid WHERE NOT g.tgisinternal AND g.tgenabled = 'D' AND c.relnamespace IN ('public'::regnamespace, 'security_audit'::regnamespace)) THEN RAISE EXCEPTION 'PRECHECK: a trigger is already disabled'; END IF;
  IF (SELECT count(*) || ':' || md5(string_agg(k, E'\\n' ORDER BY k COLLATE "C")) FROM (SELECT n.nspname||'.'||c.relname||'.'||x.conname||'|'||pg_get_constraintdef(x.oid) AS k FROM pg_constraint x JOIN pg_class c ON c.oid=x.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE x.contype IN ('p','u','f') AND n.nspname IN ('public','security_audit')) s) IS DISTINCT FROM '%d:%s' THEN RAISE EXCEPTION 'PRECHECK: FK / key inventory changed since the review'; END IF;
  IF (SELECT count(*) || ':' || md5(string_agg(k, E'\\n' ORDER BY k COLLATE "C")) FROM (SELECT n.nspname||'.'||c.relname||'.'||g.tgname||'|'||g.tgenabled::text||'|'||pg_get_triggerdef(g.oid) AS k FROM pg_trigger g JOIN pg_class c ON c.oid=g.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE NOT g.tgisinternal AND n.nspname IN ('public','security_audit')) s) IS DISTINCT FROM '%d:%s' THEN RAISE EXCEPTION 'PRECHECK: trigger inventory changed since the review'; END IF;
END $pre$;
""" % (nfk, fk, ntrg, trg)
hdr = "-- GENERATED by build_single_call.py from wipe_operational_data.sql (sha256 %s). Paste ALL of it into ONE Supabase SQL editor run (role postgres).\n" % EXPECT_SHA
(here / "RUN_1_DRYRUN_SINGLE_CALL.sql").write_text(hdr + "-- RUN 1: DRY RUN. Returns one row. Changes nothing.\n" + script + wrapper + "SELECT pg_temp.dry_report('%s'::jsonb) AS dry_run_result;\n" % q(dry))
(here / "RUN_2_REAL_SINGLE_CALL.sql").write_text(hdr + "-- RUN 2: REAL WIPE. Only with Rhys's explicit GO after RUN 1 was read. One call = one transaction: commits only if every check inside passes, otherwise nothing changes.\n" + pre + script + "SELECT pg_temp.tolra_wipe('%s'::jsonb) AS wipe_report;\n" % q(real))
print("built")
